patch:
--- a/rtl/spi_master_core.v
+++ b/rtl/spi_master_core.v
@@ -22,7 +22,6 @@
         cs_n <= 1;
         busy <= 0;
         done <= 0;
-        bit_count <= 0;
     end else begin
         case (state)
             IDLE: begin
@@ -31,8 +30,6 @@
                     state <= SHIFT;
                     cs_n <= 0;
                     busy <= 1;
-                    shift_reg <= data_in;
-                    bit_count <= 7;
                 end
             end
             SHIFT: begin
@@ -51,14 +48,21 @@
     end
 end

-// Shift on negedge sclk
+// Shift and load on negedge sclk
 always @(negedge sclk or negedge rst_n) begin
     if (!rst_n) begin
         mosi <= 0;
-    end else if (state == SHIFT) begin
-        mosi <= shift_reg[7];
-        shift_reg <= shift_reg << 1;
-        bit_count <= bit_count - 1;
+        shift_reg <= 0;
+        bit_count <= 0;
+    end else begin
+        if (state == IDLE && start) begin
+            shift_reg <= data_in;
+            bit_count <= 7;
+        end else if (state == SHIFT) begin
+            mosi <= shift_reg[7];
+            shift_reg <= shift_reg << 1;
+            bit_count <= bit_count - 1;
+        end
     end
 end

--- a/rtl/baud_tick_gen.v
+++ b/rtl/baud_tick_gen.v
@@ -8,7 +8,7 @@
     output reg tick
 );
     localparam DIVISOR = CLK_FREQ / BAUD_RATE;
-    reg [15:0] counter;
+    reg [31:0] counter;
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             counter <= 0;
--- a/rtl/uart_tx_core.v
+++ b/rtl/uart_tx_core.v
@@ -38,7 +38,10 @@
                 end
                 DATA: begin
                     tx <= shift_reg[0];
-                    shift_reg <= {1'b0, shift_reg[7:1]}; // LSB first
+                    if (baud_tick) begin
+                        shift_reg <= {1'b0, shift_reg[7:1]};
+                        bit_index <= bit_index + 1;
+                    end
                     busy <= 1;
                 end
                 STOP: begin
@@ -54,11 +57,8 @@
             IDLE: if (start) next_state = START;
             START: if (baud_tick) next_state = DATA;
             DATA: if (baud_tick) begin
-                if (bit_index == 7) begin
-                    next_state = STOP;
-                end else begin
-                    bit_index = bit_index + 1;
-                end
+                if (bit_index == 7) next_state = STOP;
+                else next_state = DATA;
             end
             STOP: if (baud_tick) next_state = IDLE;
         endcase

--- a/sim/tb_top.v
+++ b/sim/tb_top.v
@@ -1,3 +1,4 @@
+`timescale 1ns/1ps
 module tb_top;
     reg clk;
     reg rst_n;
@@ -27,7 +28,7 @@
         $finish;
     end
     initial begin
-        #2000;
+        #200000;
         $display("TEST_FAIL (timeout)");
         $finish;
     end
